# Pasadizo, south hut (the underground passage between Ruta 5 and Ruta 6, C3, contract 34), 8 x 7, interior. column = i, row = j. The rest stop: a vending machine, a television with the
# news, benches, flowerbeds, the ladder up from the passage (a floor hatch, the door L) and the door mat to Ruta 6.
@map pasadizo_s
@size 8 7
@interior yes
@bg 3
@fill floor_wood
@spawn door 3 5 N
@spawn ladder 4 2 S             # arriving from the passage
@legend
  .  tile=floor_wood
  C  tile=none object=wall_corner
  w  tile=none object=wall_j
  y  tile=none object=wall_win_j
  |  tile=none object=wall_i
  q  tile=none object=wall_win_i
  M  object=machine interact=look text=pasadizo.vending
  V  object=tv interact=look text=obj.tv
  B  object=bench
  x  object=flowerbed
  L  tile=floor_wood door=rope_ladder
  G  npc=vecino_m id=guest face=W text=pasadizo.guest
  m  tile=mat
@grid
  Cwwwywww
  |MV.L.Bx
  |.......
  |.....B.
  q.....G.
  |......x
  |..mm...
@warp m -> ruta_6 spawn=hut_door
@warp L -> pasadizo spawn=south
